INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47611, 'Proverbs 18:7', 'Proverbs', 18, 7, 'د کم‌عقل انسان خپله ژبه بلا ده او شونډې یې د ځان دپاره دام دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_7.mp3', '', 1761754199, 1761754199),
(47612, 'Proverbs 18:8', 'Proverbs', 18, 8, 'د غیبت کوونکي خبرې د خوندور خوراک په شان دي چې د انسان له ستوني تېریږي او د ګېډې تل ته ښکته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_8.mp3', '', 1761754199, 1761754199),
(47613, 'Proverbs 18:9', 'Proverbs', 18, 9, 'څوک چې په خپل کار کې لټي کوي نو د ورانکارو سره ورورولي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_9.mp3', '', 1761754199, 1761754199),
(47614, 'Proverbs 18:10', 'Proverbs', 18, 10, 'د څښتن نوم ټینګ او قوي مورچل دی چې نېک انسان هلته پناه اخلي او په امن کې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_10.mp3', '', 1761754199, 1761754199),
(47615, 'Proverbs 18:11', 'Proverbs', 18, 11, 'د شتمن مال دولت د هغه دپاره ټینګه کلا ده او فکر کوي چې د هغه دپاره یو لوړ دېوال دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_11.mp3', '', 1761754199, 1761754199),
(47616, 'Proverbs 18:12', 'Proverbs', 18, 12, 'کبر د تباهۍ سبب کیږي او عاجزي د سرلوړۍ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_12.mp3', '', 1761754199, 1761754199),
(47617, 'Proverbs 18:13', 'Proverbs', 18, 13, 'څوک چې د خبرو د اورېدلو نه مخکې ځواب ورکوي نو دا د هغه دپاره جهالت او رسوایي راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_13.mp3', '', 1761754199, 1761754199),
(47618, 'Proverbs 18:14', 'Proverbs', 18, 14, 'د انسان روح ناروغي زغملی شي خو خفه روح هېڅوک زغملی نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_14.mp3', '', 1761754199, 1761754199),
(47619, 'Proverbs 18:15', 'Proverbs', 18, 15, 'عقلمن انسان تل د علم حاصلولو په لټون کې وي او د هوښیار انسان غوږونه تل د علم زده کړې ته تیار وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_15.mp3', '', 1761754199, 1761754199),
(47620, 'Proverbs 18:16', 'Proverbs', 18, 16, 'سوغات ورکول د انسان دپاره لار خلاصوي او د لویو خلکو سره پېژندګلوي پیدا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_16.mp3', '', 1761754199, 1761754199),
(47621, 'Proverbs 18:17', 'Proverbs', 18, 17, 'څوک چې په محکمه کې لومړی خبرې کوي بې‌ګناه ښکاري ترڅو بل څوک د هغه څېړنه ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_17.mp3', '', 1761754199, 1761754199),
(47622, 'Proverbs 18:18', 'Proverbs', 18, 18, 'د پچې په اچولو جګړې ختمیږي او د مخالفینو ترمنځ پرېکړې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_18.mp3', '', 1761754199, 1761754199),
(47623, 'Proverbs 18:19', 'Proverbs', 18, 19, 'د مرور ورور پخلا کول د قوي ښار د فتح کولو نه سخت دي او شخړې کول د کلا دروازو ته د اړمونو ایښودلو په څېر دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_19.mp3', '', 1761754199, 1761754199),
(47624, 'Proverbs 18:20', 'Proverbs', 18, 20, 'هوښیارې خبرې د ښې ډوډۍ په شان انسان مړوي او سمې خبرې د خلکو د رضایت سبب ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_20.mp3', '', 1761754199, 1761754199),
(47625, 'Proverbs 18:21', 'Proverbs', 18, 21, 'په مرګ او ژوند کې د ژبې اختیار شته څوک چې ورسره مینه لري، د خپلو خبرو مېوه به وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_21.mp3', '', 1761754199, 1761754199),
(47626, 'Proverbs 18:22', 'Proverbs', 18, 22, 'چاته چې ښځه پیدا شي د نعمت خاوند شي او د څښتن رضا او خوشحالي حاصله کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_22.mp3', '', 1761754199, 1761754199),
(47627, 'Proverbs 18:23', 'Proverbs', 18, 23, 'مسکین په عاجزۍ زاري کوي خو شتمن سخت ځواب ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_23.mp3', '', 1761754199, 1761754199),
(47628, 'Proverbs 18:24', 'Proverbs', 18, 24, 'تش په نامه دوستان یو بل ته کنده کیندي خو رښتینی ملګری د خپل ورور نه هم نژدې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs18_verse_24.mp3', '', 1761754199, 1761754199),
(47629, 'Psalms 79:1', 'Psalms', 79, 1, 'ای خدایه، پردي قومونو ستا په خاوره باندې برید کړی بې‌حرمتي ستا د سپېڅلي کور ده کړې هغوی او اورشلیم یې بدل کړی کنډواله باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_1.mp3', '', 1761754199, 1761754199),
(47630, 'Psalms 79:2', 'Psalms', 79, 2, 'کړل جسدونه یې د ستا د بندګانو د مرغانو خوراک ستا د وفادارو د بدن غوښې شوې د ځنګل د ځناورو خوراک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_2.mp3', '', 1761754199, 1761754199),
(47631, 'Psalms 79:3', 'Psalms', 79, 3, 'د اوبو په شان یې وینې بهولې ستا د خلکو ټول اورشلیم کې بهېدلې وینې داسې څوک نه ؤ چې یې ښخ کړي مړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_3.mp3', '', 1761754199, 1761754199),
(47632, 'Psalms 79:4', 'Psalms', 79, 4, 'د شاوخوا قومونو د پېغور شولو مونږ مونږ پورې خاندي او په مونږ باندې ملنډې وهي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_4.mp3', '', 1761754199, 1761754199),
(47633, 'Psalms 79:5', 'Psalms', 79, 5, 'ای څښتنه، ته به په مونږ باندې په قهر یې همېش؟ ترڅو بلیږي به غیرت د ستا لکه د اور په شان؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_5.mp3', '', 1761754199, 1761754199),
(47634, 'Psalms 79:6', 'Psalms', 79, 6, 'قهر نازل دې کړه ته هغو قومونو باندې چې تا نه پېژني په هغو پاچاهیو باندې چې ستا نوم نه اخلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_6.mp3', '', 1761754199, 1761754199),
(47635, 'Psalms 79:7', 'Psalms', 79, 7, 'ځکه چې دوی ده قتل کړې د یعقوب اولاده هم تباه کړی یې هېواد د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_7.mp3', '', 1761754199, 1761754199),
(47636, 'Psalms 79:8', 'Psalms', 79, 8, 'مه راکوه مونږ ته سزا خپلو نیکونو د ګناه په خاطر زمونږ په حال باندې زر رحم وکړه ځکه چې ډېر خوار او زار شوي یو مونږ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_8.mp3', '', 1761754199, 1761754199),
(47637, 'Psalms 79:9', 'Psalms', 79, 9, 'ای خدایه، ای زمونږ ژغورونکیه خدایه مونږه سره مرسته وکړه د خپل نوم د جلال په خاطر ګناهونه زمونږ معاف کړه نجات راکړه د خپل نوم په خاطر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_9.mp3', '', 1761754199, 1761754199),
(47638, 'Psalms 79:10', 'Psalms', 79, 10, 'ولې قومونه مونږ نه وکړي دا سوال چې ستاسو خدای چېرته دی؟ پرېږده مونږ ووینو چې ته هغو قومونو نه بدل واخلې په دې خاطر چې هغوی ستا د خادمانو بهولې وینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_10.mp3', '', 1761754199, 1761754199),
(47639, 'Psalms 79:11', 'Psalms', 79, 11, 'د بندیانو زګېروي واوره څوک چې په مرګ محکوم دي کړه ته ازاد هغوی په خپل لوی قدرت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_11.mp3', '', 1761754199, 1761754199),
(47640, 'Psalms 79:12', 'Psalms', 79, 12, 'اووه چنده ورکړه ته سزا هغوی ته ای څښتنه هغو قومونو ګاونډیو ته چې ستا یې سپکاوی کړی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_12.mp3', '', 1761754199, 1761754199),
(47641, 'Psalms 79:13', 'Psalms', 79, 13, 'نو بیا به مونږه چې یو ستا قوم، ستا د رمې پسونه کړو همېشه به مونږ مننه ستا نه نسل په نسل به کوو مونږه ستاینه د ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms79_verse_13.mp3', '', 1761754199, 1761754199),
(47642, 'Psalms 106:1', 'Psalms', 106, 1, 'د څښتن ثنا او صفت وکړئ! د څښتن شکر کوئ، ځکه چې نېک دی هغه ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_1.mp3', '', 1761754199, 1761754199),
(47643, 'Psalms 106:2', 'Psalms', 106, 2, 'څوک کولای شي بیان کړي د هغه عظیم کارونه؟ څوک په پوره توګه کولای شي صفت یې وکړي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_2.mp3', '', 1761754199, 1761754199),
(47644, 'Psalms 106:3', 'Psalms', 106, 3, 'بختور هغه دي چې کړي انصاف د نورو سره چې تل دپاره نېک کارونه کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_3.mp3', '', 1761754199, 1761754199),
(47645, 'Psalms 106:4', 'Psalms', 106, 4, 'احسان کوې چې په خپل قوم، ما هم په یاد ساته ماته هم راکړه نجات کله چې نجات ته ورکوې هغوی ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_4.mp3', '', 1761754199, 1761754199),
(47646, 'Psalms 106:5', 'Psalms', 106, 5, 'چې غوره شوی قوم زه ستا نېکمرغه ووینمه او له هغوی سره خوشحاله اوسم او ستا د خلکو په ویاړونو کې شریک شمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_5.mp3', '', 1761754199, 1761754199),
(47647, 'Psalms 106:6', 'Psalms', 106, 6, 'مونږه ګناه کړې ده لکه چې کړې وه نیکونو زمونږ مونږه ګناه او بد عمل کړی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_6.mp3', '', 1761754199, 1761754199),
(47648, 'Psalms 106:7', 'Psalms', 106, 7, 'زمونږ نیکونه نه شول پوه مصر کې په عجیبه کارو د خدای باندې هغوی کړه هېره د هغه ډېره، تلپاتې مینه سرې بحیرې په غاړه وکړه سرکښي یې مقابل کې د ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_7.mp3', '', 1761754199, 1761754199),
(47649, 'Psalms 106:8', 'Psalms', 106, 8, 'خو دوی ته وریې کړ نجات د خپل نامه په خاطر ترڅو چې وښایي خپل لوی قدرت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_8.mp3', '', 1761754199, 1761754199),
(47650, 'Psalms 106:9', 'Psalms', 106, 9, 'سره بحیره چې هغه ورټله وچه شوله قوم یې خپل تېر کړ د دریاب په منځ کې لکه د دښتې په څېر وچه شوله ځمکه ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_9.mp3', '', 1761754199, 1761754199),
(47651, 'Psalms 106:10', 'Psalms', 106, 10, 'هغوی یې وژغورل د لاسه د هغو خلکو چې کړله کرکه یې له دوی څخه هغوی یې خلاص کړل د خپلو دښمنانو د منګولو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_10.mp3', '', 1761754199, 1761754199),
(47652, 'Psalms 106:11', 'Psalms', 106, 11, 'خو اوبو ډوب کړل د هغوی بدخواهان حتی یو کس هم ژوندی پاتې نه شو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_11.mp3', '', 1761754199, 1761754199),
(47653, 'Psalms 106:12', 'Psalms', 106, 12, 'بیا د هغه قوم اعتبار وکړ د ده په وعده د ثنا او صفت سندره یې هغه ته وویله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_12.mp3', '', 1761754199, 1761754199),
(47654, 'Psalms 106:13', 'Psalms', 106, 13, 'خو هغوی زر هغه کارونه هېر کړل کوم چې څښتن کړي وو او نصیحت ته د هغه ونه کړ دوی انتظار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_13.mp3', '', 1761754199, 1761754199),
(47655, 'Psalms 106:14', 'Psalms', 106, 14, 'سخته اشتها د هغوی دښته کې پیدا شوه د خوړو لره او په صحرا کې یې په خدای ازمېښت وکړلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_14.mp3', '', 1761754199, 1761754199),
(47656, 'Psalms 106:15', 'Psalms', 106, 15, 'نو څه چې غوښتي وو هغوی هغه یې ورکړل ورته خو رانازل یې کړ په دوی باندې مرګونی مرض', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_15.mp3', '', 1761754199, 1761754199),
(47657, 'Psalms 106:16', 'Psalms', 106, 16, 'کله هغوی چې کینه وکړه موسی سره د دښتې کمپ کې او هم هارون سره وقف شوی چې څښتن لره ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_16.mp3', '', 1761754199, 1761754199),
(47658, 'Psalms 106:17', 'Psalms', 106, 17, 'بیا خوله خلاصه کړله ځمکې او ژوندی یې تېر کړ داتان او په کې ښخ شول ابیرام او د هغه خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_17.mp3', '', 1761754199, 1761754199),
(47659, 'Psalms 106:18', 'Psalms', 106, 18, 'اور شو نازل په پیروانو د دوی د اور لمبې وسوځول هغه بدکاره خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_18.mp3', '', 1761754199, 1761754199),
(47660, 'Psalms 106:19', 'Psalms', 106, 19, 'د سینا غره کې هغوی جوړ کړ د سرو زرو خوسی او عبادت یې وکړ جوړ شوي بت ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_19.mp3', '', 1761754199, 1761754199),
(47661, 'Psalms 106:20', 'Psalms', 106, 20, 'هغوی بدل خپل جلالي خدای کړلو د یو غویي مجسمې ته چې ؤ خوراک یې واښه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_20.mp3', '', 1761754199, 1761754199),
(47662, 'Psalms 106:21', 'Psalms', 106, 21, 'هغوی هېر کړلو خپل ژغورونکی خدای تر‌سره کړي لوی کارونه چې یې مصر کې وو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_21.mp3', '', 1761754199, 1761754199),
(47663, 'Psalms 106:22', 'Psalms', 106, 22, 'څه معجزې چې هغه کړې وې د حام په وطن هم یې کړل هېر هغه عجیبه کارونه تر‌سره کړي یې چې وو سرې بحیرې په غاړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_22.mp3', '', 1761754199, 1761754199),
(47664, 'Psalms 106:23', 'Psalms', 106, 23, 'نو کله چې وویل خدای چې به خپل قوم تباه کړي د هغه غوره شوی خدمتګار موسی راودرېد د هغوی د شفاعت دپاره چې قهر یې سوړ کړي او تباه نه کړي دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_23.mp3', '', 1761754199, 1761754199),
(47665, 'Psalms 106:24', 'Psalms', 106, 24, 'بیا هغوی وکړلو انکار د هغه ښه وطن د تللو ځینې ځکه چې نه یې درلود باور د خدای په وعده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_24.mp3', '', 1761754199, 1761754199),
(47666, 'Psalms 106:25', 'Psalms', 106, 25, 'خپلو خېمو کې شول پاتې ګورېدل هغوی نه یې منله د څښتن خبره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_25.mp3', '', 1761754199, 1761754199),
(47667, 'Psalms 106:26', 'Psalms', 106, 26, 'نو هغه پورته کړ خپل لاس قسم یې وخوړ ورته چې په دې دښته کې به مړه کړي هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_26.mp3', '', 1761754199, 1761754199),
(47668, 'Psalms 106:27', 'Psalms', 106, 27, 'خوره وره به اولاده یې کړي پردو قومونو کې چې هغوی مړه شي په پردیو وطنونو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_27.mp3', '', 1761754199, 1761754199),
(47669, 'Psalms 106:28', 'Psalms', 106, 28, 'بیا په فغور کې د خدای قوم کړلو ځان وقف بعل ته او بتانو ته ورکړل شوې قربانۍ یې خوړلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_28.mp3', '', 1761754199, 1761754199),
