(47673, 'Psalms 106:32', 'Psalms', 106, 32, 'د مریبه د چینو څنګ کې دوی څښتن غوسه کړ شولو موسی د دوی له لاسه په کړاو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_32.mp3', '', 1761754199, 1761754199),
(47674, 'Psalms 106:33', 'Psalms', 106, 33, 'هغوی کړ دومره د موسی حالت تریخ چې یې راووتل د خولې نه بې‌سنجشه الفاظ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_33.mp3', '', 1761754199, 1761754199),
(47675, 'Psalms 106:34', 'Psalms', 106, 34, 'نه کړل تباه دوی بېګانه قومونه څنګه څښتن چې ؤ ورکړی حکم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_34.mp3', '', 1761754199, 1761754199),
(47676, 'Psalms 106:35', 'Psalms', 106, 35, 'ټینګې اړیکې د دوستۍ یې کړلې هغو سره او د هغوی بد رواجونه یې خپل کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_35.mp3', '', 1761754199, 1761754199),
