(47679, 'Psalms 106:38', 'Psalms', 106, 38, 'د بې‌ګناهو ماشومانو وینه یې تویه کړله د خپلو لوڼو او زامنو وینه چې قرباني یې کړل بتانو د کنعان ته هغوی په وینو ولړله ځمکه هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_38.mp3', '', 1761754199, 1761754199),
(47680, 'Psalms 106:39', 'Psalms', 106, 39, 'خپلو اعمالو باندې کړل یې خپل ځانونه ناپاک او بې‌وفا شول خدای ته د زناکارې ښځې په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_39.mp3', '', 1761754199, 1761754199),
(47681, 'Psalms 106:40', 'Psalms', 106, 40, 'څښتن په قهر شو په خپل قوم باندې شولو بېزار له خپلو خلکو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_40.mp3', '', 1761754199, 1761754199),
(47682, 'Psalms 106:41', 'Psalms', 106, 41, 'پردي قومونو ته یې تسلیم کړل هغوی هغو حکومت کاوه په دوی چې ترې نفرت یې کاوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_41.mp3', '', 1761754199, 1761754199),
(47683, 'Psalms 106:42', 'Psalms', 106, 42, 'دښمنانو د هغوی کاوه پرې ظلم وو سخت ذلیل د دوی تر لاس لاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_42.mp3', '', 1761754199, 1761754199),
(47684, 'Psalms 106:43', 'Psalms', 106, 43, 'څښتن څو ځلې وژغوره خپل ولس خو دوی د هغه مقابل کې سرکښي غوره کړه او په ګناه کې ډوب شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_43.mp3', '', 1761754199, 1761754199),
(47685, 'Psalms 106:44', 'Psalms', 106, 44, 'خو بیاهم هغه په دوی باندې به رحم کاوه چې کله وو به مصیبت کې هغوی او اورېده به یې فریاد د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_44.mp3', '', 1761754199, 1761754199),
(47686, 'Psalms 106:45', 'Psalms', 106, 45, 'هغه رایاد کړلو خپل لوظ د هغوی په خاطر او کړه بدله پرېکړه یې په سبب د خپلې تلپاتې زیاتې مینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_45.mp3', '', 1761754199, 1761754199),
(47687, 'Psalms 106:46', 'Psalms', 106, 46, 'کړل هغوی ته یې خواخوږي هغه خلک چې اسیران وو دوی له هغو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_46.mp3', '', 1761754199, 1761754199),
(47688, 'Psalms 106:47', 'Psalms', 106, 47, 'وژغوره مونږ، زمونږ څښتنه خدایه مونږ یوځای سره راټول کړه له قومونو ترڅو ادا کړو مونږه شکر د ستا ستا د سپېڅلي نوم ثنا مو ویاړ شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_47.mp3', '', 1761754199, 1761754199),
(47689, 'Psalms 106:48', 'Psalms', 106, 48, 'ثنا او صفت دې وي د اسراییلو څښتن خدای ته وکړئ ثنا او صفت یې د ازل نه تر ابده پورې بیا دې ووایي ټول قوم: «امین» ثنا او صفت دې وي څښتن ته!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms106_verse_48.mp3', '', 1761754199, 1761754199),
(47690, 'Psalms 131:1', 'Psalms', 131, 1, 'ای څښتنه، زما په زړه کې کبر نشته زما په سترګو کې غرور نشته نه کوم فکر هغه څه په هکله چې دي بهر زما له وسه یا هغو کارو په هکله چې ډېر سخت دي راته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms131_verse_1.mp3', '', 1761754199, 1761754199),
(47691, 'Psalms 131:2', 'Psalms', 131, 2, 'بلکې ارام او خاموش مې کړ ځان لکه ماشوم چې د خپلې مور غېږ کې ارام پروت وي نو داسې ماشوم په شان مې زړه دی ارام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms131_verse_2.mp3', '', 1761754199, 1761754199),
(47692, 'Psalms 131:3', 'Psalms', 131, 3, 'ای اسراییلو، په څښتن باندې باور ولرئ له همدا‌اوس نه تر ابده پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms131_verse_3.mp3', '', 1761754199, 1761754199),
(47693, 'Ezekiel 40:1', 'Ezekiel', 40, 1, 'دا د نوي کال لسمه ورځ وه او زمونږ د جلاوطنۍ پنځه ویشتم کال او د اورشلیم د سقوط څوارلسم کال ؤ. په هماغه ورځ ما د څښتن قوي حضور احساس کړ او زه یې هلته بوتلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_1.mp3', '', 1761754199, 1761754199),
(47694, 'Ezekiel 40:2', 'Ezekiel', 40, 2, 'خدای زه په رویا کې د اسراییلو وطن ته بوتلم او په یو لوړ غره باندې یې ودرولم. د جنوب خواته یو څو ودانۍ وې چې د ښار په شان ښکاره کېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_2.mp3', '', 1761754199, 1761754199),
(47695, 'Ezekiel 40:3', 'Ezekiel', 40, 3, 'کله چې هغه هلته نژدې بوتلم، ما یو سړی ولیده چې د برنجو په شان ځلېده. هغه د یوې دروازې په خوله کې ولاړ ؤ چې د کتان فیته او د اندازه کولو یو لرګی ورسره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_3.mp3', '', 1761754199, 1761754199),
(47696, 'Ezekiel 40:4', 'Ezekiel', 40, 4, 'هغه ماته وویل: «ای فاني انسانه، وګوره. په غور سره غوږ ونیسه او څه چې درته ښایم، نو هغو ته ښه پام کوه، ځکه چې ته دلته د همدې دپاره راوستل شوی یې. هرڅه چې وینې، نو هغه د اسراییلو خلکو ته ووایه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_4.mp3', '', 1761754199, 1761754199),
(47697, 'Ezekiel 40:5', 'Ezekiel', 40, 5, 'ما چې کوم شی ولیده هغه د عبادت ځای ؤ او ګردچاپېره ورڅخه دېوال راتاو شوی ؤ. د هغه سړي سره خپل د اندازه کولو لرګی ؤ چې درې متره یې اوږدوالی ؤ. هغه دېوال اندازه کړ، دېوال درې متره لوړ او درې متره پنډوالی یې درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_5.mp3', '', 1761754199, 1761754199),
(47698, 'Ezekiel 40:6', 'Ezekiel', 40, 6, 'بیا هغه د ختیځې دروازې خواته لاړ. هغه په زینه باندې پورته وخوت او د دروازې خوله یې اندازه کړه او هغه درې متره اوږده وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_6.mp3', '', 1761754199, 1761754199),
(47699, 'Ezekiel 40:7', 'Ezekiel', 40, 7, 'د دروازې دننه، د دهلېز په دواړو خواوو کې درې درې وړې کوټې وې. هره کوټه یې درې متره مربع وه او د هغو ترمنځ د دېوال پنډوالی دوه نیم متره ؤ. د هغې د دروازې خوله چې باندینۍ حویلۍ ته داخلیږي، اوږدوالی یې درې متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_7.mp3', '', 1761754199, 1761754199),
(47700, 'Ezekiel 40:10', 'Ezekiel', 40, 10, 'دا وړې کوټې د ختیځې دروازې د دهلېز په دواړو خواوو کې یوه اندازه وې او د هغوی ترمنځ د دېوالونو پنډوالی هم یوشان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_10.mp3', '', 1761754199, 1761754199),
(47701, 'Ezekiel 40:11', 'Ezekiel', 40, 11, 'بیا هغه سړي د دروازې د چوکاټ تر منځ فاصله اندازه کړه. هغه پنځه متره پلن ؤ، سره له دې چې د دهلېز پراخوالی شپږنیم متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_11.mp3', '', 1761754199, 1761754199),
(47702, 'Ezekiel 40:12', 'Ezekiel', 40, 12, 'د هرې وړې کوټې په مخکې یو ټیټ دېوال ؤ چې نیم متر لوړوالی یې درلود او نیم متر یې پنډوالی ؤ. هره کوټه درې درې متره مربع وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_12.mp3', '', 1761754199, 1761754199),
(47703, 'Ezekiel 40:13', 'Ezekiel', 40, 13, 'بیا هغه د یوې کوټې د شا دېوال نه د بلې مخامخ کوټې د شا د دېوال پورې فاصله اندازه کړه او هغه دولس نیم متره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_13.mp3', '', 1761754199, 1761754199),
(47704, 'Ezekiel 40:14', 'Ezekiel', 40, 14, 'هغه د دواړو دروازو تر منځ دهلېز اندازه کړ چې تر حوېلۍ پورې رسېدلې ؤ او اوږدوالی یې دېرش متره ؤ. باندینۍ حوېلۍ د دهلېز په درېو خواوو کې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_14.mp3', '', 1761754199, 1761754199),
(47705, 'Ezekiel 40:15', 'Ezekiel', 40, 15, 'د باندینۍ دروازې نه د دنننۍ دروازې تر اخره پورې ټوله فاصله پنځه ویشت متره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_15.mp3', '', 1761754199, 1761754199),
(47706, 'Ezekiel 40:16', 'Ezekiel', 40, 16, 'د ټولو کوټو په باندینیو دېوالونو او همدارنګه د کوټو په منځ کې په دنننیو دېوالونو کې وړې وړې کړکۍ‌ګانې وې. دهلېز ته مخامخ په دننني دېوالونو کې هم کړکۍ‌ګانې وې. دننني دېوالونه او چوکاټونه د خرما د ونو په تصویرونو باندې ښکلي کړای شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_16.mp3', '', 1761754199, 1761754199),
(47707, 'Ezekiel 40:17', 'Ezekiel', 40, 17, 'هغه سړي زه د دروازې له لارې باندینۍ حوېلۍ ته بوتلم. په هغه ځای کې باندیني دېوال ته مخامخ دېرش کوټې جوړې شوې وې او هغو ته مخامخ یوه لاره وه چې په تیږو باندې فرش شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_17.mp3', '', 1761754199, 1761754199),
(47708, 'Ezekiel 40:18', 'Ezekiel', 40, 18, 'دا فرش شوې لاره د دهلېز په دواړو خواوو کې غزېدلې وه. څومره چې دهلېز اوږد ؤ، هغومره دا لاره پراخه وه. د دې لارې سطح د دنننۍ حوېلۍ د سطحې نه ټیټه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_18.mp3', '', 1761754199, 1761754199),
(47709, 'Ezekiel 40:19', 'Ezekiel', 40, 19, 'ختیځې دروازې ته مخامخ یوه بله پورتنۍ دروازه وه چې دنننۍ حوېلۍ ته خلاصېدله. کله چې هغه د دواړو دروازو تر منځ فاصله اندازه کړه، نو هغه پنځوس متره وه. هغه بیا د ختیځې خوا نه شمال خواته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_19.mp3', '', 1761754199, 1761754199),
(47710, 'Ezekiel 40:20', 'Ezekiel', 40, 20, 'یوه شمالي دروازه وه چې باندینۍ حویلۍ ته د ننوتلو لاره وه. هغه سړي د هغې دروازې اوږدوالی او پراخوالی اندازه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_20.mp3', '', 1761754199, 1761754199);